#### Example 3: Component Access Tier Metadata

```typescript
// components.metadata.ts
export interface ComponentMetadata {
  name: string;
  tier: 'public' | 'partner' | 'internal';
  license: string;
  ipSensitivity: 'low' | 'medium' | 'high';
  allowedIPClassifications: ('gainwell-owned' | 'state-exclusive' | 'customer-owned' | 'shared')[];
}

export const ComponentRegistry: ComponentMetadata[] = [
  {
    name: 'Button',
    tier: 'public',
    license: 'Proprietary-Permissive',
    ipSensitivity: 'low',
    allowedIPClassifications: ['gainwell-owned', 'state-exclusive', 'customer-owned', 'shared']
  },
  {
    name: 'AdvancedDataGrid',
    tier: 'partner',
    license: 'Proprietary-Restricted',
    ipSensitivity: 'high',
    allowedIPClassifications: ['gainwell-owned', 'shared']
  },
  {
    name: 'AdminPanel',
    tier: 'internal',
    license: 'Proprietary-Internal',
    ipSensitivity: 'high',
    allowedIPClassifications: ['gainwell-owned']
  }
];

// Runtime access check
export function validateComponentAccess(
  componentName: string,
  ipClassification: string
): { allowed: boolean; reason?: string } {
  const metadata = ComponentRegistry.find(c => c.name === componentName);
  if (!metadata) {
    return { allowed: false, reason: 'Component not found' };
  }

  if (!metadata.allowedIPClassifications.includes(ipClassification as any)) {
    return {
      allowed: false,
      reason: `Component "${componentName}" (${metadata.tier} tier) not available for ${ipClassification} extensions`
    };
  }

  return { allowed: true };
}
```
